            close('no_promise', np[0] if np else (r or 'refused'))
            return
        close('no_promise', r or 'refused')
    if ev == 'unclear_who':
        if n >= 2:
            close('not_reached', 'unclear')
    elif ev == 'wrong_number':
        close('not_reached', 'wrong_number')
