            if not vars.get('promised'):
                vars['bye_line'] = 'I am sorry, I could not record the promise. Thank you for your time. Goodbye.'
    elif ev == 'done':
        left = [p['id'] for p in P if (p['id'] + ',') not in str(vars.get('promised') or '') and (p['id'] + '=') not in str(vars.get('notes') or '')]
        if stage == 'post' and multi and left and n < 2 and not vars.get('transfer_reason'):
